// ---------------------------------------------------------------------------
// Pipeline: N-stage conserving material delay
// ---------------------------------------------------------------------------

#[derive(Clone, Debug)]
pub struct Pipeline {
    stages: Vec<f64>,
}

impl Pipeline {
    pub fn new(stages: usize, initial_flow: f64) -> Self {
        Pipeline { stages: vec![initial_flow; stages] }
    }

    /// Advance one year; returns delivered outflow.
    pub fn step(&mut self, inflow: f64) -> f64 {
        let mut carry = inflow;
        for slot in self.stages.iter_mut() {
            std::mem::swap(slot, &mut carry);
        }
        carry
    }

    /// Advance one year with post-singularity acceleration: after the
    /// normal step, pull `extra` (0..=1) of each stage's remaining material
    /// forward one slot (the last stage's fraction is delivered). Conserving.
    pub fn step_accel(&mut self, inflow: f64, speedup: f64) -> f64 {
        let mut out = self.step(inflow);
        let extra = (speedup - 1.0).clamp(0.0, 1.0);
        if extra > 0.0 {
            let n = self.stages.len();
            for i in (0..n).rev() {
                let mv = self.stages[i] * extra;
                self.stages[i] -= mv;
                if i == n - 1 {
                    out += mv;
                } else {
                    self.stages[i + 1] += mv;
                }
            }
        }
        out
    }

    pub fn in_transit(&self) -> f64 {
        self.stages.iter().sum()
    }

    pub fn first_stage(&self) -> f64 {
        self.stages.first().copied().unwrap_or(0.0)
    }
}

fn logistic(x: f64) -> f64 {
    1.0 / (1.0 + (-x).exp())
}

