// Simulation
// ---------------------------------------------------------------------------

fn power_orders(p: &Params, power_margin: f64, perceived_growth: f64,
                current_rate: f64, ceiling_mult: f64) -> f64 {
    let excess = (power_margin - p.normal_margin).max(0.0);
    let growth = (p.power_base_growth
        + p.loops.b1_supply_response * p.power_supply_gain * excess
        + 0.3 * (perceived_growth - 0.3).max(0.0))
        .min(p.power_growth_ceiling * ceiling_mult);
    current_rate * (1.0 + growth)
}

pub fn simulate(p: &Params) -> Vec<YearState> {
    let l = &p.loops;

    let mut compute_stock = 1.0_f64;
    let mut algo_eff = 1.0_f64;
    let mut ai_power = p.ai_power_2026;
    let mut chip_capacity = p.chip_capacity_2026;
    let mut ip_capacity = chip_capacity * 0.18;
    let mut component_capacity = 0.0_f64;
    let mut robot_fleet = 0.0_f64;
    let mut cum_robots = 0.02_f64;
    let mut robot_cost = p.robot_cost_2028_k;
    #[allow(unused_assignments)]
    let mut human_cog_m = p.cognitive_workers_m;
    let mut phys_workers_m = p.physical_workers_m;
    let mut gdp = p.world_gdp;
    let mut sector_debt = 0.0_f64;
    let mut perceived_growth = p.demand_growth_base;
    let mut last_capex = p.ai_capex_2026 * 0.8;
    let mut last_desired = p.ai_capex_2026;
    let mut prev_disp = 0.0_f64;
    let mut prev_disp_macro = 0.0_f64;
    let mut prev_adopt = 0.08_f64;

    // Society layer state (endogenous political economy).
    let soc_on = l.society_layer > 0.0;
    let mut soc = SocietyState::new(&p.society);
    let mut prev_adopt_soc = 0.0_f64;
    let mut dread_armed = false;

    // Demography: dynamic pools + political signal filter. Steps BEFORE
    // society each year; prior-year outputs modulate this year's loops.
    let demo_on = l.d_demography > 0.0;
    let mut demo = DemographyState::new(
        &p.demography, p.cognitive_workers_m, p.physical_workers_m);
    let mut demo_out: Option<DemographyOutputs> = None;

    // Space: launch learning + orbital compute (B11 rent-clipper).
    let mut space = SpaceState::new(&p.space);

    // Geopolitics: metals index is mean-reverting (half-life ~2.5yr);
    // onshoring scares boost the supply response for 4 years.
    let mut metals_index = 1.0_f64;
    let mut onshoring_until = i32::MIN;
    let mut invaded = false;
    let mut gw_per_unit = p.gw_per_compute_unit;

    let mut power_pipe = Pipeline::new(p.power_pipeline_stages, p.power_additions_2026);
    let mut chip_pipe = Pipeline::new(p.chip_pipeline_stages,
                                      chip_capacity * p.chip_base_growth);
    let mut ip_pipe = Pipeline::new(p.chip_pipeline_stages,
                                    ip_capacity * p.chip_base_growth);
    let mut comp_pipe = Pipeline::new(p.component_pipeline_stages, 0.0);

    let mut silicon_margin = p.normal_margin + 0.10;
    let mut prev_ip_util = 1.05_f64;
    // the ordering RATE is its own stock — never read back from the pipeline,
    // whose stages are mutated by acceleration (bug found via the fizzle>
    // baseline capex anomaly)
    let mut power_order_rate = p.power_additions_2026;
    let mut ip_toll_margin = p.normal_margin + 0.15;
    let mut power_margin = p.normal_margin + 0.08;
    let mut component_margin = p.normal_margin;

    let mut out: Vec<YearState> = Vec::new();

    for year in p.start_year..=p.end_year {
        // ---- space: step on prior-year power rents (B11 gate) ----
        let power_rent_index = ((power_margin - p.normal_margin)
            / (p.margin_ceiling - p.normal_margin))
            .clamp(0.0, 1.0);
        space.step(&p.space, year, power_rent_index, l.r5_launch_learning);

        // ---- geopolitical shock effects for this year ----
        let gfx = geopolitics::effects_for_year(&p.geo_shocks, year);
        if gfx.chip_destruction > 0.0 {
            chip_capacity *= 1.0 - gfx.chip_destruction;
            ip_capacity *= 1.0 - gfx.chip_destruction * 0.5;
            invaded = true;
        }
        if gfx.onshoring {
            onshoring_until = onshoring_until.max(year + 4);
        }
        // Metals index chases the shock target, mean-reverts otherwise.
        metals_index += if gfx.metals_target > metals_index {
            0.8 * (gfx.metals_target - metals_index)
        } else {
            0.25 * (1.0 - metals_index) // half-life ~2.5yr
        };
        let onshoring_boost = if year <= onshoring_until { 1.5 } else { 1.0 };
        let t_sing = year - p.singularity_year;

        // ---- R1: recursive AI (saturating) ----
        if year > p.start_year {
            let g = if year <= p.singularity_year {
                p.algo_eff_growth_pre
            } else if t_sing <= p.recursive_years {
                let boost = 1.0 + (p.singularity_boost - 1.0) * l.r1_recursive_ai;
                p.algo_eff_growth_pre * boost
            } else {
                p.algo_eff_growth_post
            };
            let headroom = (1.0 - algo_eff / p.algo_eff_cap).max(0.0);
            algo_eff *= 1.0 + (g - 1.0) * headroom;
        }

        // ---- demand side: adoption with B2 + B3 ----
        let recent_disp_rate = if out.len() >= 2 {
            (out[out.len() - 1].cog_displacement
                - out[out.len() - 2].cog_displacement).max(0.0)
        } else if !out.is_empty() {
            out[out.len() - 1].cog_displacement
        } else {
            0.0
        };
        // B2 gain is endogenous when the society layer is on: a pulse
        // shaped by sentiment, labor power, transfers, and trust —
        // peaking with the displacement rate and fading after (design
        // doc §5.1) — instead of a constant.
        let mut soc_mult = if soc_on {
            soc.backlash_multiplier(&p.society, recent_disp_rate)
        } else {
            1.0
        };
        if let Some(d) = &demo_out {
            // Grievance redirection: scapegoating routes backlash away
            // from AI firms (conserved flow — pro-adoption short-run,
            // socially corrosive via the unrest multiplier below).
            soc_mult *= 1.0 - d.backlash_redirect.min(0.5);
        }
        let friction = 1.0 + l.b2_backlash * p.backlash_gain * recent_disp_rate * soc_mult;

        let btl_price = if let Some(prev) = out.last() {
            let b = prev.power_utilization.max(prev.chip_utilization);
            ((b - p.target_utilization).max(0.0) / (1.0 - p.target_utilization))
                .min(1.5)
        } else {
            0.4
        };
        let afford = 1.0 + l.b3_affordability * p.afford_gain * btl_price;

        let pre_ramp = (0.08 * 1.6_f64.powi(year - p.start_year)).min(0.28);
        let adopt_raw = if t_sing < 0 {
            pre_ramp
        } else {
            let k = 3.0_f64.ln() / (p.adoption_halflife * friction);
            logistic(k * (t_sing as f64 - p.adoption_halflife * friction))
                .max(pre_ramp)
                .max(0.10)
        };
        // Regulation slows the adoption RATE (GDPR: -25% at full
        // enforcement) and consumer trust caps the LEVEL (B10); neither
        // can un-adopt, so adoption stays a ratchet.
        let adopt = if soc_on {
            let capped = adopt_raw.min(soc.adoption_ceiling(&p.society));
            (prev_adopt_soc
                + (capped - prev_adopt_soc).max(0.0)
                    * soc.adoption_rate_mult(&p.society))
                .max(prev_adopt_soc)
        } else {
            adopt_raw
        };
        prev_adopt_soc = adopt;

        // Concave returns to intelligence: anchored at t0 where
        // compute_stock * algo_eff = 1, so rho only shapes GROWTH.
        let ai_hew_raw = p.ai_hew_2026_m
            * (compute_stock * algo_eff).max(1e-12).powf(p.intelligence_returns_rho);
        let price_ratio = if t_sing >= 0 { p.ai_task_price_rel * afford } else { 0.25 };
        let task_expansion = price_ratio
            .powf(-(p.cognitive_demand_elasticity - 1.0) * 0.35)
            .min(6.0);
        let cognitive_task_index = 1.0 + (task_expansion - 1.0) * adopt;
        let addressable = p.cognitive_workers_m * p.addressable_cognitive;
        let demand_hew = addressable * adopt * cognitive_task_index;
        let ai_hew = ai_hew_raw.min(demand_hew);

        let disp_target = (ai_hew / cognitive_task_index.max(1e-9)).min(addressable)
            / p.cognitive_workers_m;
        let mut disp = (disp_target * (adopt * 1.4).min(1.0))
            .min(prev_disp + p.max_displacement_rate / friction);
        disp = disp.max(prev_disp);
        prev_disp = disp;
        human_cog_m = p.cognitive_workers_m * (1.0 - disp);

        // ---- R4: physical acceleration factor (0 pre-singularity,
        // ramping toward 1 as ASI diffuses into engineering practice) ----
        let asi = if t_sing >= 0 {
            l.r4_physical_acceleration
                * (1.0 - (-((t_sing as f64) + 1.0) / p.asi_diffusion_years).exp())
        } else {
            0.0
        };
        let speedup = 1.0 + asi * p.asi_delay_compression;
        let ceiling_mult = 1.0 + asi * p.asi_ceiling_boost;

        // ---- R3: capex desire from perceived demand ----
        let mut demand_signal_growth = p.demand_growth_base;
        if t_sing >= 0 {
            demand_signal_growth += 1.6 * (adopt - prev_adopt).max(0.0) + 0.5 * adopt;
        }
        if soc_on {
            // Precautionary savings: elevated sentiment cuts consumption
            // before displacement does (GFC +4pp saving rate).
            demand_signal_growth -= soc.precautionary_drag(&p.society);
        }
        let adopt_delta = (adopt - prev_adopt).max(0.0);
        prev_adopt = adopt;
        perceived_growth += p.perception_smoothing
            * (demand_signal_growth - perceived_growth);
        let herd = l.r3_capex_momentum * p.momentum_gain * perceived_growth.max(0.0);
        // B3 closure: bottleneck prices throttle desired capex growth.
        // Desire base avoids the absorbing zero-capex state (round-2 fix 2).
        let desire_base = last_capex.max(0.3 * last_desired);
        let desired_capex = desire_base * (1.0 + (perceived_growth + herd) / afford)
            * gfx.demand_mult;
        last_desired = desired_capex;

        // ---- B4: credit ----
        let ai_revenue_proxy = (out.last().map_or(0.02, |s| s.pools.ai_services)
            + 0.25 * last_capex)
            .max(0.05);
        let leverage = sector_debt / ai_revenue_proxy.max(1e-9);
        // Society-layer injections into B4 (the ONLY financial channel):
        // sovereign crowding-out from debt-financed transfers plus the R7
        // regulatory-cost spiral (armed only by a dread incident).
        let soc_credit = if soc_on {
            soc.credit_injection(&p.society, dread_armed)
        } else {
            0.0
        };
        let credit_mult = 1.0
            / (1.0 + l.b4_credit
                * (p.credit_gain * (leverage - p.debt_revenue_tolerance).max(0.0)
                    + soc_credit
                    + gfx.spread));

        // ---- constraints ----
        let hw_cost_index = (1.0 - p.hw_cost_decline).powi(year - p.start_year);
        let cost_per_unit = (p.ai_capex_2026 / 0.80) * hw_cost_index;

        // deliver chip + ip capacity at the START of the year (same-year
        // convention as power); orders use last year's margins.
        let excess_margin = (silicon_margin - p.normal_margin).max(0.0);
        // Onshoring scares boost the supply response x1.5 for 4 years
        // (China WFE localization tripled post-Oct-2022); post-invasion
        // rebuild is EUV-capped at ~18%/yr regardless of price signal.
        let mut chip_growth = (p.chip_base_growth
            + l.b1_supply_response * p.chip_supply_gain * excess_margin
                * onshoring_boost)
            .min(p.chip_growth_ceiling * ceiling_mult);
        if invaded {
            chip_growth = chip_growth.min(0.18);
        }
        let chip_delivery = chip_pipe.step_accel(chip_capacity * chip_growth, speedup);
        chip_capacity += chip_delivery;
        // The IP toll's pace is strategic: a monopolist expands only under
        // excess demand and never into slack (defending price is what market
        // power means). ASI acceleration does not apply to it either.
        let ip_expand = p.chip_base_growth
            * ((prev_ip_util - 0.95) / 0.40).clamp(0.0, 1.0);
        let ip_delivery = ip_pipe.step(ip_capacity * ip_expand);
        ip_capacity += ip_delivery;

        let chips_cap = chip_capacity * gfx.chip_mult / p.silicon_share_of_capex;
        if year > p.start_year {
            gw_per_unit *= 1.0 - p.power_efficiency_gain;
        }
        let orders = power_orders(p, power_margin, perceived_growth,
                                  power_order_rate,
                                  1.0 + asi * p.asi_ceiling_boost * 0.5);
        power_order_rate = orders;
        // Shock haircut on energization (blockade: no GPUs to fill halls;
        // the lost flow is destroyed, not deferred — war losses).
        let power_additions = power_pipe.step_accel(orders, speedup) * gfx.power_mult;
        let power_headroom = (ai_power + space.orbital_gw_equiv + power_additions
            - compute_stock * gw_per_unit)
            .max(0.0);
        let power_cap = (power_headroom / gw_per_unit) * cost_per_unit;
        let capital_cap = gdp * p.capex_gdp_cap * credit_mult;

        let caps = [
            (Binding::Chips, chips_cap),
            (Binding::Power, power_cap),
            (Binding::Capital, capital_cap),
            (Binding::Demand, desired_capex),
        ];
        let (mut binding, mut ai_capex) = (Binding::Chips, chips_cap);
        for &(b, v) in &caps[1..] {
            if v < ai_capex {
                binding = b;
                ai_capex = v;
            }
        }
        let queue_ratio = (desired_capex
            / chips_cap.min(power_cap).min(capital_cap).max(1e-9))
            .min(50.0);
        let capacity_glut = (chip_capacity
            / (desired_capex * p.silicon_share_of_capex).max(1e-9))
            .min(50.0);

        sector_debt = sector_debt * p.debt_amortization
            + (ai_capex * (1.0 - p.internal_funding_share)).max(0.0);

        let pre_stock = compute_stock;
        let units_added = ai_capex / cost_per_unit;
        compute_stock = compute_stock * (1.0 - p.compute_deprec) + units_added;
        ai_power += power_additions;
        let used_power = (compute_stock * gw_per_unit).min(ai_power);

        // ---- utilizations, prices, margins ----
        let chip_utilization = (desired_capex * p.silicon_share_of_capex
            / chip_capacity.max(1e-9))
            .min(1.35);
        // IP demand is the same 18% slice of silicon flow its capacity
        // serves (round-2 review fix).
        let ip_utilization = (desired_capex * p.silicon_share_of_capex * 0.18
            / ip_capacity.max(1e-9))
            .min(1.35);
        prev_ip_util = ip_utilization;
        let power_demand_gw = pre_stock * (1.0 - p.compute_deprec) * gw_per_unit
            + (desired_capex / cost_per_unit) * gw_per_unit;
        let power_utilization = (power_demand_gw
            / (ai_power + space.orbital_gw_equiv).max(1e-9))
            .min(1.35);

        let margin_from = |u: f64, gain_class: f64| -> f64 {
            let excess = (u - p.target_utilization).max(0.0)
                / (1.0 - p.target_utilization);
            (p.normal_margin + p.rent_margin_slope * excess.min(2.0) * gain_class)
                .min(p.margin_ceiling)
        };

        let pa = p.price_adjustment;
        silicon_margin += pa * (margin_from(chip_utilization, 0.9) - silicon_margin);
        ip_toll_margin += pa * (margin_from(ip_utilization, 0.9) - ip_toll_margin);
        power_margin += pa * (margin_from(power_utilization, 1.0) - power_margin);
        let electricity_price = p.electricity_price_normal
            * (1.0 + 1.2 * (((power_utilization - p.target_utilization).max(0.0))
                / (1.0 - p.target_utilization))
                .min(2.0));

        // ---- robotics ----
        let mut robot_prod = 0.0;
        // Price actually PAID this year (shock premia included); the
        // Wright's-law learning state stays on the clean cost curve.
        let mut robot_cost_paid = robot_cost;
        if year >= p.robotics_year {
            if component_capacity == 0.0 {
                component_capacity = p.component_capacity_2028;
            }
            let comp_excess = (component_margin - p.normal_margin).max(0.0);
            let bootstrap = l.r2_robot_bootstrap * p.bootstrap_gain
                * (robot_fleet * 0.3).min(10.0);
            let comp_ceiling = p.component_growth_ceiling + bootstrap;
            let comp_growth = (p.component_base_growth
                + l.b1_supply_response * p.component_supply_gain * comp_excess
                + bootstrap * 0.2)
                .min(comp_ceiling * ceiling_mult);
            component_capacity +=
                comp_pipe.step_accel(component_capacity * comp_growth, speedup);

            let avg_phys_wage_k =
                p.physical_wage_bill / p.physical_workers_m * 1e3;
            // Minerals shocks pass through to delivered robot cost
            // (magnets 5-10% of humanoid BOM; copper elasticity 0.08).
            let robot_cost_eff =
                robot_cost * gfx.comp_cost_mult * metals_index.powf(0.08);
            robot_cost_paid = robot_cost_eff;
            let payback_years =
                robot_cost_eff / (avg_phys_wage_k * p.robot_hew).max(1e-9);
            let econ_pull = (2.0 / payback_years.max(0.25)).clamp(0.0, 3.0);
            let t_rob = (year - p.robotics_year) as f64;
            // ASI dissolves integration friction: the adoption midpoint moves
            // from ~4 years toward ~2 as robots self-integrate.
            let midpoint = 4.0 * (1.0 - p.asi_integration_relief * asi);
            let deploy_ramp = logistic(0.9 * (t_rob - midpoint));
            let (phys_pool, addressable) = match &demo_out {
                Some(d) => (d.phys_pool_m, d.physical_addressable_eff),
                None => (p.physical_workers_m, p.physical_addressable),
            };
            let care_pull = demo_out.as_ref().map_or(0.0, |d| d.robot_pull_units_m);
            let fleet_target = phys_pool * addressable
                * deploy_ramp * (econ_pull / 2.0).min(1.0)
                + care_pull;
            let robot_demand = (fleet_target
                - robot_fleet * (1.0 - p.robot_attrition))
                .max(p.robot_prod_2028_m * 0.5);
            // A minerals embargo is a hard supply gate: ex-China magnet
            // capacity caps western output regardless of price.
            robot_prod = robot_demand.min(component_capacity * gfx.comp_supply_mult);
            let comp_utilization = robot_demand / component_capacity.max(1e-9);
            component_margin += p.price_adjustment
                * (margin_from(comp_utilization.min(1.35), 0.8) - component_margin);

            cum_robots += robot_prod;
            let doublings = (cum_robots / 0.06).max(1.0).log2();
            robot_cost = (p.robot_cost_2028_k
                * (1.0 - p.robot_learning_rate).powf(doublings))
                .max(p.robot_cost_floor_k);
            robot_fleet = robot_fleet * (1.0 - p.robot_attrition) + robot_prod;
        }

        let phys_hew = robot_fleet * p.robot_hew;
        let demo_phys_pool =
            demo_out.as_ref().map_or(p.physical_workers_m, |d| d.phys_pool_m);
        let pd_target = (phys_hew / demo_phys_pool).min(
            demo_out
                .as_ref()
                .map_or(p.physical_addressable, |d| d.physical_addressable_eff),
        );
        let prev_pd = 1.0 - phys_workers_m / p.physical_workers_m;
        let pd = pd_target
            .min(prev_pd + p.max_physical_displacement_rate)
            .max(prev_pd);
        phys_workers_m = p.physical_workers_m * (1.0 - pd);

        // ---- pools & profits ----
        let avg_cog_wage = p.cognitive_wage_bill / p.cognitive_workers_m;
        let avg_phys_wage = p.physical_wage_bill / p.physical_workers_m;
        let displaced_value = disp * p.cognitive_workers_m * avg_cog_wage;
        let ai_services = displaced_value * 0.45
            + (cognitive_task_index - 1.0) * p.cognitive_wage_bill * 0.06;

        let years_in = year - p.start_year;
        let casualty = |pool0: f64, beta: f64, drift: f64| -> f64 {
            let organic = pool0 * (1.0 + drift).powi(years_in);
            organic * (1.0 - beta * disp).max(0.05)
        };

        let pools = Pools {
            ai_services,
            silicon: ai_capex * p.silicon_share_of_capex,
            ip_tolls: ai_capex * 0.10,
            dc_infra: ai_capex * (1.0 - p.silicon_share_of_capex),
            power_equipment: p.power_equip_cost_per_gw * power_additions,
            electricity: used_power * 8760.0 * electricity_price / 1e6,
            robots: robot_prod * robot_cost_paid / 1e3,
            robot_components: robot_prod * robot_cost_paid / 1e3 * 0.55,
            robot_services: pd * p.physical_workers_m * avg_phys_wage * 0.35,
            it_services: casualty(p.it_services_pool, p.it_services_beta, 0.04),
            bpo: casualty(p.bpo_pool, p.bpo_beta, 0.03),
            seat_saas: casualty(p.seat_saas_pool, p.saas_beta, 0.08),
            prof_info: casualty(p.prof_info_pool, p.prof_info_beta, 0.05),
            human_cognitive_wages: human_cog_m * avg_cog_wage,
            human_physical_wages: phys_workers_m * avg_phys_wage,
            gdp_index: gdp,
        };
        let electricity_margin = (0.30
            + 0.5 * (electricity_price / p.electricity_price_normal - 1.0))
            .min(0.6);
        let profits = Profits {
            ai_services: pools.ai_services * p.ai_services_margin,
            silicon: pools.silicon * silicon_margin,
            ip_tolls: pools.ip_tolls * ip_toll_margin,
            dc_infra: pools.dc_infra * p.normal_margin,
            power_equipment: pools.power_equipment * power_margin,
            electricity: pools.electricity * electricity_margin,
            robots: pools.robots * p.normal_margin,
            robot_components: pools.robot_components * component_margin,
            robot_services: pools.robot_services * p.normal_margin,
            it_services: pools.it_services * p.normal_margin,
            bpo: pools.bpo * p.normal_margin,
            seat_saas: pools.seat_saas * p.normal_margin,
            prof_info: pools.prof_info * p.normal_margin,
        };

        // ---- macro ----
        let new_disp = (disp - prev_disp_macro).max(0.0);
        prev_disp_macro = disp;
        let ai_share = (ai_services + pools.robot_services) / gdp;
        // Transfers offset part of transition drag (demand backstop);
        // compliance costs subtract (distinct channels, design doc §5.4).
        let drag_mult = if soc_on { soc.drag_multiplier(&p.society) } else { 1.0 };
        // Compliance is a cost on the AI SECTOR's output, not the whole
        // economy (red-team round 3: charging world GDP overstated the
        // loss by the inverse of the sector share).
        let compliance = if soc_on {
            soc.compliance_cost(&p.society) * ai_share.min(0.2) * 5.0
        } else {
            0.0
        };
        let unrest_cost = if soc_on { soc.unrest_gdp_cost() } else { 0.0 };
        gdp *= 1.0
            + (p.base_gdp_growth + p.productivity_passthrough * ai_share * 0.5
                - p.transition_drag * new_disp * (p.cognitive_wage_bill / gdp)
                    * drag_mult
                - compliance
                - unrest_cost);

        // ---- demography advances first: it filters what politics sees ----
        let election = (year - p.start_year) % p.society.election_period == 0;
        let gdp_growth_this_year = if let Some(prev) = out.last() {
            gdp / prev.gdp - 1.0
        } else {
            p.base_gdp_growth
        };
        let this_demo = if demo_on {
            let d = demo.step(
                &p.demography,
                disp,
                robot_prod * p.robot_hew,
                soc.sentiment,
                soc.transfer_share(),
                gdp_growth_this_year,
                election,
                pd,
            );
            Some(d)
        } else {
            None
        };

        // ---- society stocks advance on this year's outcomes ----
        if soc_on {
            let lag = p.society.erosion_lag as usize;
            let lagged_rate = if out.len() >= lag + 1 {
                (out[out.len() - lag].cog_displacement
                    - out[out.len() - lag - 1].cog_displacement)
                    .max(0.0)
            } else {
                0.0
            };
            let incident = p.incident_year == year;
            if incident && p.incident_dread {
                dread_armed = true;
            }
            // Demography rewires the political inputs: society sees the
            // VISIBLE displacement rate (net of hiring freezes, vacancy
            // filling, restriction masking) against an endogenous
            // attrition threshold, and transfer size/cap gate on
            // solidarity + fiscal aging.
            let (soc_rate, sp_eff, suppress_transfers) = match &this_demo {
                Some(d) => {
                    let mut sp = p.society.clone();
                    sp.attrition_threshold = d.attrition_threshold;
                    sp.transfer_cap = d.transfer_cap_eff;
                    sp.transfer_step *= d.transfer_step_mult;
                    sp.transfer_crisis_step *= d.transfer_step_mult;
                    if d.restriction_fired {
                        // restriction-first: the cheap valve fires INSTEAD
                        // of the transfer step this cycle
                        sp.b5_relief = 0.0;
                    }
                    (
                        d.visible_cog_rate + d.visible_phys_rate,
                        sp,
                        d.restriction_fired,
                    )
                }
                None => (new_disp, p.society.clone(), false),
            };
            soc.step(
                &sp_eff,
                soc_rate,
                adopt,
                adopt_delta,
                lagged_rate,
                election,
                incident,
                incident && p.incident_dread,
            );
            if let Some(d) = &this_demo {
                // Channel B (youth blockage) is a SEPARATE sentiment
                // inflow — the historically revolutionary variable; it
                // never touches labor_power (blocked youth can't strike).
                soc.sentiment = (soc.sentiment
                    + d.youth_sentiment_inflow * (1.0 - soc.sentiment))
                    .min(1.0);
                if suppress_transfers {
                    // restriction vents SALIENCE, not grievance
                    soc.sentiment = (soc.sentiment
                        - p.demography.restriction_sent_relief)
                        .max(0.0);
                }
                // tension multiplies the unrest hazard (IMF/Barrett
                // self-excitation), applied to the boil level
                soc.unrest =
                    (soc.unrest * (1.0 + 0.5 * (d.unrest_mult - 1.0))).min(1.0);
            }
        }
        demo_out = this_demo;

        last_capex = ai_capex.max(1e-6);

        out.push(YearState {
            year,
            binding,
            ai_capex,
            compute_stock,
            algo_eff,
            ai_power_gw: used_power,
            power_utilization,
            chip_utilization,
            silicon_margin,
            power_margin,
            component_margin,
            electricity_price,
            ai_hew_m: ai_hew,
            cog_displacement: disp,
            cognitive_task_index,
            adoption_friction: friction,
            adoption_level: adopt,
            robot_prod_m: robot_prod,
            robot_fleet_m: robot_fleet,
            robot_cost_k: robot_cost,
            component_capacity_m: component_capacity,
            phys_displacement: pd,
            sector_debt,
            credit_multiplier: credit_mult,
            perceived_growth,
            queue_ratio,
            capacity_glut,
            ip_toll_margin,
            gdp,
            sentiment: soc.sentiment,
            reg_enforcement: soc.reg_enforcement,
            transfer_share: soc.transfer_share(),
            labor_power: soc.labor_power,
            inst_trust: soc.inst_trust,
            consumer_trust: soc.consumer_trust,
            blocked_entrants_m: demo.blocked_entrants_m,
            visible_disp_rate: demo_out
                .as_ref()
                .map_or(new_disp, |d| d.visible_cog_rate + d.visible_phys_rate),
            tension: demo.tension,
            solidarity: demo.solidarity,
            migration_openness: demo.migration_openness,
            cog_pool_m: demo.cog_pool_m,
            phys_pool_m: demo.phys_pool_m,
            autonomization_index: (ai_capex / gdp)
                / ((pools.human_cognitive_wages + pools.human_physical_wages)
                    / gdp)
                    .max(1e-9),
            meltdown_ratio: new_disp.max(0.0)
                / (soc.transfer_share() + soc.reg_enforcement + 0.02),
            orbital_gw_equiv: space.orbital_gw_equiv,
            launch_cost_per_kg: space.launch_cost_per_kg,
            launch_capacity_tpy: space.launch_capacity_tpy,
            pools,
            profits,
        });
    }

    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn pipeline_conserves() {
        let mut pipe = Pipeline::new(2, 0.0);
        let mut total_in = 0.0;
        let mut total_out = 0.0;
        for i in 0..10 {
            let inflow = i as f64;
            total_in += inflow;
            total_out += pipe.step(inflow);
        }
        assert!((total_in - total_out - pipe.in_transit()).abs() < 1e-9);
    }

    #[test]
    fn baseline_runs_and_power_binds() {
        let states = simulate(&Params::default());
        assert_eq!(states.len(), 11);
        let power_years = states.iter()
            .filter(|s| s.binding == Binding::Power).count();
        assert!(power_years >= 6, "power bound {} years", power_years);
    }
}
